import { useEffect, useState } from 'react';
import { Combobox, InputBase, useCombobox, type InputBaseProps } from '@mantine/core';
import { useUncontrolled } from '@mantine/hooks';
import { POPULAR_DESTINATIONS } from '../data';
import { getPlace, getPlaceLabel, getSideLabel, placesOverlap, searchPlaces } from '../places';
import type { Place, Side } from '../types';
import { PlaceOption } from './PlaceOption';

interface PlaceInputProps extends Omit<InputBaseProps, 'value' | 'defaultValue' | 'onChange'> {
  label: string;
  placeholder: string;
  value?: string | null;
  defaultValue?: string | null;
  onChange?: (value: string | null) => void;
  onFocus?: (event: React.FocusEvent<HTMLInputElement>) => void;
  onBlur?: (event: React.FocusEvent<HTMLInputElement>) => void;
  otherSide: Side;
  otherValue: string | null;
  recent: string[];
  onPick?: (code: string) => void;
}

export function PlaceInput({
  value,
  defaultValue,
  onChange,
  onFocus,
  onBlur,
  otherSide,
  otherValue,
  recent,
  onPick,
  ...others
}: PlaceInputProps) {
  const [current, setCurrent] = useUncontrolled<string | null>({
    value,
    defaultValue,
    finalValue: null,
    onChange,
  });
  // null while the input shows the selected place, a string while the user is typing
  const [search, setSearch] = useState<string | null>(null);

  const combobox = useCombobox({
    onDropdownClose: () => combobox.resetSelectedOption(),
  });

  const selected = getPlace(current);
  const other = getPlace(otherValue);
  const query = search ?? '';

  useEffect(() => {
    if (query.trim() !== '') {
      combobox.selectFirstOption();
    }
  }, [query]);

  const renderOption = (place: Place, nested = false) => (
    <PlaceOption
      key={place.code}
      place={place}
      nested={nested}
      active={place.code === current}
      disabledReason={other && placesOverlap(place, other) ? getSideLabel(otherSide) : null}
    />
  );

  const renderSuggestions = () => {
    const popular = POPULAR_DESTINATIONS.filter((code) => !recent.includes(code));
    return (
      <>
        {recent.length > 0 && (
          <Combobox.Group label="Recent">
            {recent.map((code) => renderOption(getPlace(code)!))}
          </Combobox.Group>
        )}
        <Combobox.Group label="Popular destinations">
          {popular.map((code) => renderOption(getPlace(code)!))}
        </Combobox.Group>
      </>
    );
  };

  const renderResults = () => {
    const results = searchPlaces(query);
    return results.length > 0 ? (
      results.map((entry) => renderOption(entry.place, entry.nested))
    ) : (
      <Combobox.Empty>No airports match “{query.trim()}”</Combobox.Empty>
    );
  };

  const handleOptionSubmit = (code: string) => {
    setCurrent(code);
    setSearch(null);
    combobox.closeDropdown();
    onPick?.(code);
  };

  const handleClear = () => {
    setCurrent(null);
    setSearch(null);
  };

  return (
    <Combobox store={combobox} onOptionSubmit={handleOptionSubmit}>
      <Combobox.Target>
        <InputBase
          {...others}
          value={search ?? (selected ? getPlaceLabel(selected) : '')}
          autoComplete="off"
          rightSection={
            selected ? (
              <Combobox.ClearButton onClear={handleClear} aria-label={`Clear ${others.label}`} />
            ) : (
              <Combobox.Chevron />
            )
          }
          rightSectionPointerEvents={selected ? 'all' : 'none'}
          onChange={(event) => {
            const text = event.currentTarget.value;
            setSearch(text);
            if (text === '' && current !== null) {
              setCurrent(null);
            }
            combobox.openDropdown();
          }}
          onClick={() => combobox.openDropdown()}
          onFocus={(event) => {
            event.currentTarget.select();
            combobox.openDropdown();
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setSearch(null);
            combobox.closeDropdown();
            onBlur?.(event);
          }}
        />
      </Combobox.Target>

      <Combobox.Dropdown>
        <Combobox.ScrollArea mah={320} viewportProps={{ tabIndex: -1 }}>
          <Combobox.Options>
            {query.trim() === '' ? renderSuggestions() : renderResults()}
          </Combobox.Options>
        </Combobox.ScrollArea>
      </Combobox.Dropdown>
    </Combobox>
  );
}

import { IconBuildingSkyscraper, IconPlane } from '@tabler/icons-react';
import { Combobox, Text } from '@mantine/core';
import type { Place } from '../types';
import classes from './PlaceInput.module.css';

interface PlaceOptionProps {
  place: Place;
  nested?: boolean;
  active: boolean;
  disabledReason: string | null;
}

export function PlaceOption({ place, nested = false, active, disabledReason }: PlaceOptionProps) {
  const Icon = place.kind === 'city' ? IconBuildingSkyscraper : IconPlane;
  const title =
    place.kind === 'city'
      ? `${place.city.name}, ${place.city.country} · All airports`
      : `${place.code} · ${place.airport.name}`;
  const details =
    place.kind === 'city'
      ? place.airports.map((airport) => airport.code).join(', ')
      : `${place.airport.city}, ${place.airport.country}`;

  return (
    <Combobox.Option
      value={place.code}
      active={active}
      disabled={disabledReason !== null}
      className={classes.option}
      data-nested={nested || undefined}
    >
      <Icon size={16} className={classes.icon} />
      <div className={classes.texts}>
        <Text size="sm" className={classes.title}>
          {title}
        </Text>
        <Text size="xs">{disabledReason ?? details}</Text>
      </div>
    </Combobox.Option>
  );
}

import { AIRPORTS, CITIES } from './data';
import type { Place, Side } from './types';

export interface SearchEntry {
  place: Place;
  nested: boolean;
}

const PLACES = new Map<string, Place>();

for (const airport of AIRPORTS) {
  PLACES.set(airport.code, { kind: 'airport', code: airport.code, airport });
}

for (const city of CITIES) {
  const airports = AIRPORTS.filter((airport) => airport.city === city.name);
  PLACES.set(city.code, { kind: 'city', code: city.code, city, airports });
}

const CITY_BY_NAME = new Map(CITIES.map((city) => [city.name, PLACES.get(city.code)!]));

export function getPlace(code: string | null): Place | null {
  return code === null ? null : (PLACES.get(code) ?? null);
}

export function getPlaceLabel(place: Place) {
  return place.kind === 'airport'
    ? `${place.code} · ${place.airport.name}`
    : `${place.city.name} · All airports`;
}

export function getPlaceShortLabel(place: Place) {
  return place.kind === 'airport' ? place.code : `${place.city.name} (all airports)`;
}

export function getAirportCodes(place: Place) {
  return place.kind === 'airport' ? [place.code] : place.airports.map((airport) => airport.code);
}

export function placesOverlap(a: Place, b: Place) {
  const codes = getAirportCodes(b);
  return getAirportCodes(a).some((code) => codes.includes(code));
}

export function getSideLabel(side: Side) {
  return side === 'from' ? 'Selected as departure' : 'Selected as destination';
}

export function normalize(text: string) {
  return text
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .trim();
}

function includesQuery(fields: string[], query: string) {
  return fields.some((field) => normalize(field).includes(query));
}

function matchesPlace(place: Place, query: string) {
  return place.kind === 'airport'
    ? includesQuery(
        [place.code, place.airport.city, place.airport.name, place.airport.country],
        query
      )
    : includesQuery([place.code, place.city.name, place.city.country], query);
}

// A matching city brings all of its airports; otherwise its airports match on their own
export function searchPlaces(search: string): SearchEntry[] {
  const query = normalize(search);
  if (query === '') {
    return [];
  }

  const blocks: SearchEntry[][] = [];
  const visitedCities = new Set<string>();

  for (const airport of AIRPORTS) {
    const city = CITY_BY_NAME.get(airport.city);

    if (city?.kind === 'city') {
      if (visitedCities.has(city.code)) {
        continue;
      }
      visitedCities.add(city.code);

      if (matchesPlace(city, query)) {
        blocks.push([
          { place: city, nested: false },
          ...city.airports.map((item) => ({ place: PLACES.get(item.code)!, nested: true })),
        ]);
      } else {
        city.airports
          .map((item) => PLACES.get(item.code)!)
          .filter((place) => matchesPlace(place, query))
          .forEach((place) => blocks.push([{ place, nested: false }]));
      }
    } else {
      const place = PLACES.get(airport.code)!;
      if (matchesPlace(place, query)) {
        blocks.push([{ place, nested: false }]);
      }
    }
  }

  const isExactCode = (block: SearchEntry[]) => block[0].place.code.toLowerCase() === query;
  return [...blocks.filter(isExactCode), ...blocks.filter((block) => !isExactCode(block))].flat();
}

export interface Airport {
  code: string;
  name: string;
  city: string;
  country: string;
}

